const net = require('net');
const { BAD_REQUEST_RESPONSE, routeRequest } = require('./router');
const { HEAD_END, parseHead } = require('./parser');

const PORT = process.env.PORT || 8080;

const readPositiveInteger = (name, defaultValue) => {
  const configuredValue = process.env[name] ?? defaultValue;
  const value = Number(configuredValue);
  if (!Number.isSafeInteger(value) || value <= 0) {
    throw new Error(`${name} must be a positive integer, got "${configuredValue}"`);
  }
  return value;
};

// Limit for the request line plus headers.
const MAX_REQUEST_LINE_BYTES = readPositiveInteger('MAX_REQUEST_LINE_BYTES', 8192);
const MAX_HEAD_BYTES = readPositiveInteger('MAX_HEAD_BYTES', 16384);
const MAX_BODY_BYTES = readPositiveInteger('MAX_BODY_BYTES', 1048576);

const server = net.createServer((conn) => {
  let receivedBytes = Buffer.alloc(0);
  let request = null; // parsed head, once complete
  let bodyStart = 0;

  const sendResponse = (response) => conn.end(response, 'latin1');

  conn.on('error', () => {});
  conn.on('data', (chunk) => {
    if (conn.writableEnded) return;
    receivedBytes = Buffer.concat([receivedBytes, chunk]);

    if (!request) {
      const headEnd = receivedBytes.subarray(0, MAX_HEAD_BYTES + HEAD_END.length).indexOf(HEAD_END);
      if (headEnd === -1) {
        const lineEnd = receivedBytes.indexOf('\r\n');
        const lineTooLong = lineEnd === -1
          ? receivedBytes.length >= MAX_REQUEST_LINE_BYTES
          : lineEnd > MAX_REQUEST_LINE_BYTES;
        if (lineTooLong || receivedBytes.length >= MAX_HEAD_BYTES) sendResponse(BAD_REQUEST_RESPONSE);
        return;
      }
      if (receivedBytes.indexOf('\r\n') > MAX_REQUEST_LINE_BYTES) {
        return sendResponse(BAD_REQUEST_RESPONSE);
      }
      request = parseHead(receivedBytes.toString('latin1', 0, headEnd));
      if (!request || request.contentLength > MAX_BODY_BYTES) {
        return sendResponse(BAD_REQUEST_RESPONSE);
      }
      bodyStart = headEnd + HEAD_END.length;
    }

    if (receivedBytes.length - bodyStart >= request.contentLength) {
      request.body = receivedBytes.subarray(bodyStart, bodyStart + request.contentLength);
      sendResponse(routeRequest(request));
    }
  });
  conn.on('end', () => {
    if (!conn.writableEnded) sendResponse(BAD_REQUEST_RESPONSE);
  });
});

server.listen(PORT);
